public class SD {
    public Schema.DescribeTabSetResult app() {
        for (Schema.DescribeTabSetResult a : Schema.describeTabs()) {
            if (a.getLabel() == 'A23 Oracle') { return a; }
        }
        return null;
    }
    public Schema.DescribeTabResult tab(String objectName) {
        for (Schema.DescribeTabResult t : app().getTabs()) {
            if (t.getSobjectName() == objectName) { return t; }
        }
        return null;
    }
    public Schema.ChildRelationship contactRelationship() {
        for (Schema.ChildRelationship c : Account.SObjectType.getDescribe().getChildRelationships()) {
            if (c.getChildSObject() == Contact.SObjectType && c.getField() == Contact.AccountId) {
                return c;
            }
        }
        return null;
    }
}
